tiledsdf = inf(tileddim,tileddim);
for j = 1:tileddim
  for i = 1:tileddim
    for l = 1:tileddim
      for k = 1:tileddim
        if (tiledroom(l,k)>0)
          md = sqrt((j-l)^2+(i-k)^2);
          if (md < tiledsdf(j,i))
            tiledsdf(j,i) = md;
